create table public.resources (
slug text primary key, title text not null, description text not null, category text not null, level text not null,
minutes integer not null check (minutes > 0), accent text not null, symbol text not null,
lines jsonb not null default '[]', activity text not null, published boolean not null default false,
sort_order integer not null default 0, created_at timestamptz not null default now()
);
create table public.project_templates (
slug text primary key, title text not null, description text not null, category text not null,
duration text not null, color text not null, symbol text not null, steps jsonb not null default '[]',
phrases jsonb not null default '[]', published boolean not null default false,
sort_order integer not null default 0, created_at timestamptz not null default now()
);
create table public.workspace_items (
id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade,
kind text not null check (kind in ('note','project','bookmark')), title text not null, content jsonb not null default '{}',
created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index workspace_items_owner_idx on public.workspace_items(owner_id);
alter table public.resources enable row level security;
alter table public.project_templates enable row level security;
alter table public.workspace_items enable row level security;
grant select on public.resources, public.project_templates to anon, authenticated;
revoke insert, update, delete on public.resources, public.project_templates from anon, authenticated;
grant select, insert, update, delete on public.workspace_items to authenticated;
revoke all on public.workspace_items from anon;
create policy "Read published lessons" on public.resources for select to anon, authenticated using (published = true);
create policy "Read published projects" on public.project_templates for select to anon, authenticated using (published = true);
create policy "Read own workspace" on public.workspace_items for select to authenticated using ((select auth.uid()) = owner_id);
create policy "Insert own workspace" on public.workspace_items for insert to authenticated with check ((select auth.uid()) = owner_id);
create policy "Update own workspace" on public.workspace_items for update to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
create policy "Delete own workspace" on public.workspace_items for delete to authenticated using ((select auth.uid()) = owner_id);
insert into public.resources (slug,title,description,category,level,minutes,accent,symbol,lines,activity,published,sort_order)
select slug,title,description,category,level,minutes,accent,symbol,lines,activity,published,sort_order
from jsonb_to_recordset('[{"slug":"hello","title":"你好! 첫 인사 나누기","description":"처음 만난 친구에게 중국어로 인사해 볼까요?","category":"회화","level":"입문","minutes":15,"accent":"sage","symbol":"你好","lines":[{"chinese":"你好！","pinyin":"Nǐ hǎo!","korean":"안녕!"},{"chinese":"我叫小明。","pinyin":"Wǒ jiào Xiǎomíng.","korean":"나는 샤오밍이라고 해."},{"chinese":"你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","korean":"너는 이름이 뭐야?"},{"chinese":"很高兴认识你。","pinyin":"Hěn gāoxìng rènshi nǐ.","korean":"만나서 반가워."},{"chinese":"再见！","pinyin":"Zàijiàn!","korean":"다음에 만나!"}],"activity":"짝과 역할을 바꾸어 인사하고 이름을 물어보세요. 자신의 이름은 한국어로 말해도 괜찮아요. 你好에서 연속된 3성은 실제로 앞 음절을 2성처럼 발음해요.","published":true,"sort_order":0},{"slug":"four-tones","title":"소리의 높낮이, 네 가지 성조","description":"같은 소리도 높낮이에 따라 뜻이 달라져요.","category":"발음","level":"입문","minutes":20,"accent":"butter","symbol":"ā á","lines":[{"chinese":"妈","pinyin":"mā","korean":"엄마 · 1성: 높고 평평하게"},{"chinese":"麻","pinyin":"má","korean":"삼(식물) · 2성: 아래에서 위로"},{"chinese":"马","pinyin":"mǎ","korean":"말(동물) · 3성: 낮아졌다 올라가게"},{"chinese":"骂","pinyin":"mà","korean":"꾸짖다 · 4성: 위에서 아래로"}],"activity":"손으로 높낮이 곡선을 그리며 mā, má, mǎ, mà를 읽어 보세요. 짝이 말한 성조를 손가락 1~4개로 맞혀 보세요. 3성은 문장 안에서 낮게만 발음되는 경우가 많아요.","published":true,"sort_order":1},{"slug":"numbers","title":"一二三, 숫자로 말해요","description":"1부터 10까지, 숫자로 시작하는 작은 대화.","category":"어휘","level":"입문","minutes":15,"accent":"peach","symbol":"三","lines":[{"chinese":"一、二、三","pinyin":"yī, èr, sān","korean":"1, 2, 3"},{"chinese":"四、五、六","pinyin":"sì, wǔ, liù","korean":"4, 5, 6"},{"chinese":"七、八、九、十","pinyin":"qī, bā, jiǔ, shí","korean":"7, 8, 9, 10"},{"chinese":"你几岁？","pinyin":"Nǐ jǐ suì?","korean":"너 몇 살이니? (주로 어린아이에게)"},{"chinese":"我十岁。","pinyin":"Wǒ shí suì.","korean":"나는 열 살이야."}],"activity":"1~10 중 숫자를 골라 말하고 짝이 적어 보게 하세요. 나이 질문은 인형 역할 놀이로 연습해 보세요.","published":true,"sort_order":2},{"slug":"my-day","title":"나의 하루를 소개해요","description":"학교에서 자주 쓰는 표현을 한 문장씩.","category":"회화","level":"기초","minutes":20,"accent":"sky","symbol":"每天","lines":[{"chinese":"我去学校。","pinyin":"Wǒ qù xuéxiào.","korean":"나는 학교에 가요."},{"chinese":"我学习汉语。","pinyin":"Wǒ xuéxí Hànyǔ.","korean":"나는 중국어를 공부해요."},{"chinese":"我喜欢看书。","pinyin":"Wǒ xǐhuan kàn shū.","korean":"나는 책 읽기를 좋아해요."},{"chinese":"我回家。","pinyin":"Wǒ huí jiā.","korean":"나는 집에 돌아가요."}],"activity":"하루 중 세 장면을 그림으로 그린 뒤 알맞은 문장을 적어 보세요. 짝에게 그림을 보여 주며 문장을 읽어 주세요.","published":true,"sort_order":3},{"slug":"food","title":"내가 좋아하는 중국 음식","description":"음식 이름으로 취향을 이야기해 봐요.","category":"문화","level":"기초","minutes":25,"accent":"peach","symbol":"饺子","lines":[{"chinese":"饺子","pinyin":"jiǎozi","korean":"교자(만두)"},{"chinese":"包子","pinyin":"bāozi","korean":"바오쯔(찐빵형 만두)"},{"chinese":"面条","pinyin":"miàntiáo","korean":"국수"},{"chinese":"我喜欢吃饺子。","pinyin":"Wǒ xǐhuan chī jiǎozi.","korean":"나는 만두 먹는 것을 좋아해요."},{"chinese":"你喜欢吃什么？","pinyin":"Nǐ xǐhuan chī shénme?","korean":"너는 무엇을 먹는 걸 좋아해?"}],"activity":"음식 카드를 만들어 좋아하는 것을 골라 보세요. 중국에서도 지역과 가정마다 즐겨 먹는 음식이 다르다는 점을 함께 이야기해 보세요.","published":true,"sort_order":4},{"slug":"characters","title":"그림에서 시작하는 한자","description":"日·月·山·水, 모양과 뜻을 연결해요.","category":"한자","level":"입문","minutes":20,"accent":"sage","symbol":"山","lines":[{"chinese":"日","pinyin":"rì","korean":"해, 날"},{"chinese":"月","pinyin":"yuè","korean":"달, 월"},{"chinese":"山","pinyin":"shān","korean":"산"},{"chinese":"水","pinyin":"shuǐ","korean":"물"}],"activity":"각 글자에서 떠오르는 자연의 모습을 그려 보세요. 원고지에 글자를 크게 쓰고 옆에 병음과 뜻을 적어 나만의 한자 카드를 완성하세요.","published":true,"sort_order":5}]'::jsonb) as x(slug text,title text,description text,category text,level text,minutes integer,accent text,symbol text,lines jsonb,activity text,published boolean,sort_order integer);
insert into public.project_templates (slug,title,description,category,duration,color,symbol,steps,phrases,published,sort_order)
select slug,title,description,category,duration,color,symbol,steps,phrases,published,sort_order
from jsonb_to_recordset('[{"slug":"travel","title":"우리만의 중국 여행 안내서","description":"가 보고 싶은 도시를 고르고, 함께 여행 한 페이지를 만들어요.","category":"문화 탐구","duration":"2~3차시","color":"sage","symbol":"游","steps":["모둠별로 중국의 도시 한 곳을 정하고 지도로 위치를 찾아요.","가 보고 싶은 장소와 음식을 조사하고 출처를 적어요.","인사말과 간단한 여행 표현을 넣어 안내서를 만들어요.","각 모둠의 안내서를 전시하고 여행하고 싶은 곳을 소개해요."],"phrases":[{"chinese":"我想去北京。","pinyin":"Wǒ xiǎng qù Běijīng.","korean":"나는 베이징에 가고 싶어요."},{"chinese":"这里很漂亮。","pinyin":"Zhèlǐ hěn piàoliang.","korean":"여기는 정말 아름다워요."}],"published":true,"sort_order":0},{"slug":"cafe","title":"어서 오세요, 우리 반 茶馆","description":"메뉴를 만들고 주문을 주고받는 작은 중국어 카페.","category":"역할 놀이","duration":"1~2차시","color":"butter","symbol":"茶","steps":["차와 간식 메뉴 3개를 고르고 중국어 이름을 찾아요.","가격을 정하고 그림 메뉴판을 만들어요.","점원과 손님 역할로 주문 표현을 연습해요.","역할을 바꿔 가며 우리 반 카페를 열어요."],"phrases":[{"chinese":"我要一杯茶。","pinyin":"Wǒ yào yì bēi chá.","korean":"차 한 잔 주세요."},{"chinese":"多少钱？","pinyin":"Duōshao qián?","korean":"얼마예요?"}],"published":true,"sort_order":1},{"slug":"introduce","title":"你好, 나를 소개하는 한 장","description":"이름, 취향, 꿈을 중국어와 그림으로 담아 보세요.","category":"표현 활동","duration":"1차시","color":"peach","symbol":"我","steps":["친구에게 알리고 싶은 나의 특징 3가지를 골라요.","이름과 좋아하는 것을 짧은 중국어 문장으로 적어요.","사진 대신 나를 표현하는 그림을 넣어 카드를 만들어요.","카드를 보며 짝에게 나를 소개해요."],"phrases":[{"chinese":"我叫……","pinyin":"Wǒ jiào…","korean":"내 이름은 …이야."},{"chinese":"我喜欢音乐。","pinyin":"Wǒ xǐhuan yīnyuè.","korean":"나는 음악을 좋아해요."}],"published":true,"sort_order":2}]'::jsonb) as x(slug text,title text,description text,category text,duration text,color text,symbol text,steps jsonb,phrases jsonb,published boolean,sort_order integer);
